class LocketAPI:
    def __init__(self, token=None):
        pass

    def getUserByUsername(self, username):
        """
        Cào UID chuẩn xác 100% bằng thuật toán của tool Telegram.
        """
        if not username:
            raise ValueError("Username is required")

        url = f"https://locket.cam/{username}"
        headers = {
            "User-Agent": "Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X)",
            "Accept": "text/html"
        }
        
        try:
            response = requests.get(url, headers=headers, allow_redirects=True, timeout=10)
            html_text = response.text
            redirect_url = str(response.url)

            uid = None
            
            # 1. Tìm trực tiếp
            m = re.search(r'/invites/([A-Za-z0-9]{28})', html_text)
            if m:
                uid = m.group(1)
                
            # 2. Tìm bên trong tham số mã hóa (Quan trọng nhất)
            if not uid:
                lp = re.search(r'link=([^\s"\'>]+)', html_text)
                if lp:
                    try:
                        d = lp.group(1).replace('%3A', ':').replace('%2F', '/')
                        dm = re.search(r'/invites/([A-Za-z0-9]{28})', d)
                        if dm: 
                            uid = dm.group(1)
                    except:
                        pass
                        
            # 3. Tìm từ URL chuyển hướng
            if not uid:
                m_redir = re.search(r'/invites/([A-Za-z0-9]{28})', redirect_url)
                if m_redir:
                    uid = m_redir.group(1)

            if uid:
                return {
                    "result": {
                        "data": {
                            "uid": uid,
                            "username": username,
                            "first_name": "", 
                            "last_name": f"@{username}",
                            "profile_picture_url": "" 
                        }
                    }
                }
            else:
                raise Exception("Không tìm thấy User.")
                
        except Exception as e:
            raise Exception(f"Lỗi khi tìm User: {str(e)}")

    def restorePurchase(self, uid):
        url = "https://api.revenuecat.com/v1/receipts"
        token_config = TOKEN_SETS[0]
        
        body = {
            "product_id": "locket_199_1m", 
            "fetch_token": token_config['fetch_token'], 
            "app_transaction": token_config['app_transaction'],
            "app_user_id": uid, 
            "is_restore": True, 
            "store_country": "VNM", 
            "currency": "USD",
            "price": "1.99", 
            "normal_duration": "P1M", 
            "subscription_group_id": "21419447",
            "observer_mode": False, 
            "initiation_source": "restore", 
            "offers": [],
            "attributes": { 
                "$attConsentStatus": { "updated_at_ms": int(time.time() * 1000), "value": "notDetermined" } 
            }
        }
        
        current_headers = REVENUECAT_HEADERS.copy()
        
        # BẮT BUỘC: Ép format JSON không khoảng trắng để Hash và Content-Length chuẩn xác 100%
        payload_str = json.dumps(body, separators=(',', ':'))
        current_headers['Content-Length'] = str(len(payload_str))
        
        if token_config.get('hash_params'):
            current_headers['X-Post-Params-Hash'] = token_config['hash_params']
        if token_config.get('hash_headers'):
            current_headers['X-Headers-Hash'] = token_config['hash_headers']
            
        current_headers['X-Is-Sandbox'] = str(token_config['is_sandbox']).lower()

        # Bước 1: Bơm biên lai (Inject)
        for attempt in range(3):
            try:
                # Bắt buộc dùng data=payload_str, KHÔNG dùng json=body
                response = requests.post(url, headers=current_headers, data=payload_str, timeout=15)
                
                if response.status_code == 200:
                    break
                elif response.status_code == 529:
                    time.sleep(2)
                    continue
                else:
                    err_msg = response.json().get('message', str(response.status_code))
                    raise Exception(f"RevenueCat từ chối (HTTP {response.status_code}): {err_msg}")
            except Exception as e:
                if attempt == 2:
                    raise Exception(f"Lỗi kết nối RevenueCat: {str(e)}")
                time.sleep(2)

        # Bước 2: Kiểm tra chéo (Verify Entitlement) y hệt bot Telegram
        time.sleep(1.5)
        check_url = f"https://api.revenuecat.com/v1/subscribers/{uid}"
        check_res = requests.get(check_url, headers=REVENUECAT_HEADERS, timeout=10)
        
        if check_res.status_code == 200:
            data = check_res.json()
            entitlements = data.get('subscriber', {}).get('entitlements', {}).get('Gold', {})
            
            # Kiểm tra xem tài khoản đã THỰC SỰ có Gold chưa
            if entitlements and entitlements.get('expires_date'):
                return data 
            else:
                raise Exception("Bơm thành công nhưng KHÔNG CÓ GOLD (Token Apple có thể đã chết/hết hạn).")
        else:
            raise Exception("Lỗi: Không thể xác minh trạng thái tài khoản sau khi bơm.")